function apiOf(line) {
  if (line == '备用接口') return 'http://sy.tingshu8.top/yuan1/lrts.php';
  return 'http://www.tingshu8.top/yuan1/lrts.php';
}
function pick(b) {
  return { id: b.baseEntityId || b.id, name: b.name, author: b.author, announcer: b.announcer,
           cover: b.cover, score: b.score, state: b.state, desc: b.desc,
           payType: b.payType, sections: b.sections };
}
function explore(ctx) {
  var url = ctx.url || '';
  if (url.indexOf('getBookRank') >= 0) {
    var rank = http.get(url);
    if (!rank.ok) throw new Error('榜单请求失败：HTTP ' + rank.status);
    var rj = rank.json() || {};
    return { books: (rj.list || []).map(pick) };
  }
  var m = url.match(/entityId=([0-9]+)/);
  if (!m) return { books: [] };
  var page = ctx.page > 0 ? ctx.page : 1;
  var size = 20;
  var st = (ctx.vars && ctx.vars.state) || '全部';
  var so = (ctx.vars && ctx.vars.sort) || '智能排序';
  var lb = '31000';
  if (so == '最高人气') lb = '10001';
  else if (so == '最近更新') lb = '10002';
  else if (so == '最多评论') lb = '10003';
  if (st == '连载') lb += ',10006';
  else if (st == '完结') lb += ',10005';
  else if (st == '新品') lb += ',195932';
  var ck = 'cat_' + lb + '_' + m[1];
  var books = cache.get(ck);
  if (!books) {
    var api = 'https://www.lanrentingshu.com/api/category/getResourceList?entityType=1&entityId=' + m[1] + '&pageNum=1&dsize=1000&labelIds=' + lb + '&showFilters=1';
    var raw = [];
    var lastStatus = 0;
    for (var i = 0; i < 2 && !raw.length; i++) {
      var resp = http.get(api);
      lastStatus = resp.status;
      if (resp.ok) raw = resp.json().books || [];
    }
    if (!raw.length) throw new Error(lastStatus ? '分类请求失败：HTTP ' + lastStatus : '分类接口返回空数据，请稍后重试');
    books = raw.map(pick);
    if (st == '连载') books = books.filter(function (b) { return b.state == 1; });
    else if (st == '完结') books = books.filter(function (b) { return b.state == 2; });
    if (books.length) cache.put(ck, books, 600);
  }
  var start = (page - 1) * size;
  return { books: books.slice(start, start + size), total: books.length };
}
function lineOptions(ctx) {
  var names = ['默认接口', '备用接口'];
  var alive = [];
  for (var i = 0; i < names.length; i++) {
    try {
      var r = http.get(apiOf(names[i]) + '?name=' + encodeURIComponent('道君') + '&page=1');
      if (r.ok && r.json() && r.json().code == 200) alive.push(names[i]);
    } catch (e) {}
  }
  return alive;
}

/* ===== v2 目录修复（2026-11-14）=====
 * 现象：原目录接口 m.lrts.me/ajax/getBookMenu 回 {"status":114,"msg":"非法请求AA"}，
 *       目录取不到 → 阅读器里「听不了」。搜索（包装机）、详情（官方 getBookInfo）、
 *       单集音频（包装机 ?id=<albumId>*<N>）都实测正常。
 * 做法：改用移动书页的 SSR 数据取目录——页面里直接带「第N集　标题」的完整列表。
 * 过滤：只保留 N ≤ 详情里的集数（book.vars.sections），并去重、按集号排序，
 *       避免把页面里「同类推荐」的章节混进来。
 * 待实测：站点当日对我限流（404），本条改动的联网实测需稍后补（见交付说明）。
 */
function lrtsToc(ctx) {
  // 目录：官方 m.lrts.me/ajax/getBookMenu（学自可用源的关键一招：必须带齐整套浏览器头，缺了会被「非法请求AA」拦）
  // 我们自己的增强：分页拿全量 → 以集数补全 → 官方整条失败再退到移动书页 SSR（前 50 集）→ 最后才是纯占位。
  var bid = String((ctx.book && ctx.book.vars && ctx.book.vars.bookId) || '');
  if (!bid) { var bm = String(ctx.book.bookUrl || '').match(/book\/([0-9]+)/); bid = bm ? bm[1] : ''; }
  if (!bid) { throw new Error('无法取得书号：' + ctx.book.bookUrl); }
  var total = Number((ctx.book && ctx.book.vars && ctx.book.vars.sections) || 0);
  var HDR = {
    'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 16_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/16.6 Mobile/15E148 Safari/604.1',
    'Accept': 'application/json, text/plain, */*',
    'Referer': 'https://m.lrts.me/book/' + bid,
    'Origin': 'https://m.lrts.me',
    'X-Requested-With': 'XMLHttpRequest'
  };
  function menuUrl(pn) {
    return 'https://m.lrts.me/ajax/getBookMenu?bookId=' + bid + '&pageNum=' + pn + '&pageSize=60&sortType=0';
  }
  function take(resp, map) {
    var d = null;
    try { d = JSON.parse(String((resp && resp.body) || '')); } catch (e) { return 0; }
    if (!d || Number(d.apiStatus) !== 0) { return 0; }
    var list = d.list || [], n = 0;
    for (var i = 0; i < list.length; i++) {
      var it = list[i] || {}, s = parseInt(String(it.section || 0), 10);
      if (s > 0) { if (!map[s]) { map[s] = String(it.name || ''); } n++; }
    }
    return n;
  }
  var map = {}, hits = 0;
  // ① 第 1 页探路：通了才批量（风控时只烧 1 次）
  var first = null;
  try { first = http.get(menuUrl(1), { headers: HDR, timeout: 3000 }); } catch (e) { first = null; }
  if (first && first.ok && first.status === 200) { hits += take(first, map); }
  // ② 批量取余页（并发 8）
  if (hits > 0) {
    var pages = total > 0 ? Math.ceil(total / 60) : 1;
    if (pages > 12) { pages = 12; }   // 请求预算兜底：大书只取前 12 页（720 章），其余占位
    var reqs = [], pn;
    for (pn = 2; pn <= pages; pn++) { reqs.push({ url: menuUrl(pn), headers: HDR }); }
    if (reqs.length) {
      var res = [];
      try { res = http.all(reqs, { concurrency: 8, timeout: 3500 }) || []; } catch (e2) { res = []; }
      for (var r = 0; r < res.length; r++) { hits += take(res[r], map); }
    }
  }
  // ③ 官方整条不通 → 退到移动书页 SSR（只有前 ~50 集真标题）
  if (hits === 0) {
    var hosts = ['https://m.lanrentingshu.com/book/' + bid, 'https://www.lrts.me/book/' + bid];
    for (var h = 0; h < hosts.length && hits === 0; h++) {
      var html = '';
      try {
        var rs = http.get(hosts[h], { headers: { 'User-Agent': HDR['User-Agent'], 'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8', 'Accept-Language': 'zh-CN,zh;q=0.9', 'Referer': (h === 0 ? 'https://m.lanrentingshu.com/' : 'https://www.lrts.me/') } });
        if (rs && rs.ok) { html = String(rs.body || ''); }
      } catch (e3) {}
      if (html) {
        var rex = /第(\d{1,5})集[\s\u3000]{0,3}([^\n"\\<>]{1,50})/g, m;
        while ((m = rex.exec(html)) !== null) {
          var n2 = Number(m[1]);
          if (!(n2 >= 1)) { continue; }
          if (total > 0 && n2 > total) { continue; }
          if (!map[n2]) { map[n2] = '第' + n2 + '集 ' + String(m[2] || '').replace(/[\u3000\s]+$/g, ''); hits++; }
        }
      }
    }
  }
  var api = apiOf((ctx.vars && ctx.vars.line) || '默认接口');
  var list = [];
  var maxN = total > 0 ? total : 0;
  if (!maxN) { for (var k in map) { if (map.hasOwnProperty(k)) { var kn = Number(k); if (kn > maxN) { maxN = kn; } } } }
  if (!maxN) { throw new Error('目录为空：官方接口与目录页都没取到（站点可能改版）'); }
  for (var q = 1; q <= maxN; q++) {
    var t = map[q] ? String(map[q]) : '';
    if (t.indexOf('第') !== 0) { t = '第 ' + q + '集' + (t ? ' ' + t : ''); }
    list.push({ title: t, url: api + '?id=' + bid + '*' + q, isVip: false, tag: '' });
  }
  return list;
}
